schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/agency-discovery-call-scorecard.json",
  "title": "Agency Discovery Call Scorecard rubric",
  "type": "object",
  "required": ["rubric_version", "version_date", "version_reason", "axes", "score_range", "formula", "decision_threshold", "threshold_rule", "retro"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "datetime": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "snake": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "anchor": {"type": "string", "minLength": 8, "not": {"pattern": "^(?i:poor|fair|good|excellent|strong|weak|low|medium|high)$"}}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "rubric_version": {"type": "string", "pattern": "^v[0-9]+$"},
    "version_date": {"$ref": "#/definitions/date"},
    "version_reason": {"type": "string", "minLength": 10},
    "axes": {
      "type": "array",
      "minItems": 4,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "fit"}}}},
        {"contains": {"properties": {"name": {"const": "budget"}}}},
        {"contains": {"properties": {"name": {"const": "urgency"}}}},
        {"contains": {"properties": {"name": {"const": "decision_maker"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "weight", "anchors"],
        "additionalProperties": false,
        "properties": {
          "name": {"$ref": "#/definitions/snake"},
          "weight": {"type": "number", "minimum": 0.01, "maximum": 0.5, "multipleOf": 0.01},
          "anchors": {"type": "array", "minItems": 2, "items": {"$ref": "#/definitions/anchor"}}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "budget"}}}, "then": {"properties": {"anchors": {"items": {"pattern": "[0-9]"}}}}},
          {"if": {"properties": {"name": {"const": "urgency"}}}, "then": {"properties": {"anchors": {"items": {"pattern": "(?i)(day|week|month|quarter|Q[1-4]|20[0-9]{2}|no date|no timeline)"}}}}},
          {"if": {"properties": {"name": {"const": "decision_maker"}}}, "then": {"properties": {"anchors": {"items": {"pattern": "(?i)(owner|founder|partner|director|head|manager|vp|cfo|ceo|cmo|coo|procurement|sign-off|signs|approve|authority|contributor|not discussed)"}}}}},
          {"if": {"properties": {"name": {"const": "fit"}}}, "then": {"properties": {"anchors": {"items": {"pattern": "(?i)(icp|criteria|criterion|industry|size|service line|headcount|revenue)"}}}}}
        ]
      }
    },
    "score_range": {
      "type": "object",
      "required": ["min", "max"],
      "additionalProperties": false,
      "properties": {"min": {"const": 0}, "max": {"const": 100}}
    },
    "formula": {"const": "sum(weight * anchor_index / (anchor_count - 1)) * 100"},
    "decision_threshold": {"type": "number", "exclusiveMinimum": 0, "exclusiveMaximum": 100},
    "threshold_rule": {"const": "score at or above decision_threshold advances; below is rejected or nurtured"},
    "retro": {
      "type": "object",
      "required": ["cadence", "same_version_only", "compares"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"const": "weekly"},
        "same_version_only": {"const": true},
        "compares": {
          "type": "array",
          "minItems": 2,
          "items": {"type": "string", "enum": ["advance_rate", "close_rate_of_advanced"]},
          "allOf": [{"contains": {"const": "advance_rate"}}, {"contains": {"const": "close_rate_of_advanced"}}]
        }
      }
    },
    "leads": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["lead", "call_date", "scored_at", "scorer_on_call", "rubric_version", "axis_scores", "score", "decision"],
        "additionalProperties": false,
        "properties": {
          "lead": {"type": "string", "minLength": 2},
          "call_date": {"$ref": "#/definitions/datetime"},
          "scored_at": {"$ref": "#/definitions/datetime"},
          "scorer_on_call": {"const": true},
          "rubric_version": {"type": "string", "pattern": "^v[0-9]+$"},
          "axis_scores": {
            "type": "array",
            "minItems": 4,
            "items": {
              "type": "object",
              "required": ["axis", "anchor_index", "evidence"],
              "additionalProperties": false,
              "properties": {
                "axis": {"$ref": "#/definitions/snake"},
                "anchor_index": {"type": "integer", "minimum": 0},
                "evidence": {"type": "string", "minLength": 15},
                "authority_confirmed": {"type": "boolean"}
              },
              "if": {"properties": {"axis": {"const": "decision_maker"}}},
              "then": {"required": ["authority_confirmed"]}
            }
          },
          "score": {"type": "number", "minimum": 0, "maximum": 100},
          "decision": {"type": "string", "enum": ["advance", "reject", "nurture"]}
        }
      }
    }
  }
}
